package com.lmof;

public final class JagexHSL
{
	private JagexHSL()
	{
	}

	public static int hue(int color)
	{
		return (color >> 10) & 0x3F;
	}

	public static int saturation(int color)
	{
		return (color >> 7) & 0x7;
	}

	public static int luminance(int color)
	{
		return color & 0x7F;
	}

	public static int pack(int hue, int saturation, int luminance)
	{
		return (hue << 10) | (saturation << 7) | luminance;
	}
}

package com.lmof;

public class FireColorMap
{
	private static final int COLOR_SPACE_SIZE = 65536;

	private final int[] colorMap = new int[COLOR_SPACE_SIZE];

	public void update(float intensity)
	{
		for (int color = 0; color < COLOR_SPACE_SIZE; color++)
		{
			colorMap[color] = transformColor(color, intensity);
		}
	}

	public int getFireColor(int color)
	{
		if (color < 0 || color >= COLOR_SPACE_SIZE)
		{
			return color;
		}
		return colorMap[color];
	}

	private static int transformColor(int color, float intensity)
	{
		int hue = JagexHSL.hue(color);
		int sat = JagexHSL.saturation(color);
		int lum = JagexHSL.luminance(color);

		int fireHue;
		if (lum > 80)
		{
			fireHue = 8; // yellow
		}
		else if (lum > 40)
		{
			fireHue = 5; // orange
		}
		else
		{
			fireHue = 0; // red
		}

		hue = Math.min(63, Math.max(0, Math.round(hue * (1 - intensity) + fireHue * intensity)));
		sat = Math.min(7, Math.round(sat + 3 * intensity));
		lum = Math.min(127, Math.max(0, Math.round(lum * (1.0f + 0.3f * intensity))));

		return JagexHSL.pack(hue, sat, lum);
	}
}

package com.lmof;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Scene;
import net.runelite.api.SceneTileModel;
import net.runelite.api.SceneTilePaint;
import net.runelite.api.Tile;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.OverheadTextChanged;
import net.runelite.api.events.PreMapLoad;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
	name = "Light Misthalin On Fire"
)
public class LightMisthalinOnFirePlugin extends Plugin
{
	private static final int WATER_TEXTURE = 1;
	private static final int LAVA_TEXTURE = 31;
	private static final float FIRE_INTENSITY = 0.75f;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private LightMisthalinOnFireConfig config;

	private final FireColorMap fireColorMap;
	private final FireSpawner fireSpawner = new FireSpawner();
	private final TreeReplacer treeReplacer = new TreeReplacer();
	private final NpcDialogueReplacer npcDialogueReplacer = new NpcDialogueReplacer();

	{
		fireColorMap = new FireColorMap();
		fireColorMap.update(FIRE_INTENSITY);
	}

	@Override
	protected void startUp()
	{
		log.info("[LMOF] Plugin started!");
		clientThread.invokeLater(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				client.setGameState(GameState.LOADING);
			}
		});
	}

	@Override
	protected void shutDown()
	{
		log.info("[LMOF] Plugin stopped!");
		clientThread.invokeLater(() ->
		{
			fireSpawner.clearFires();
			treeReplacer.clearDeadTrees();
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				client.setGameState(GameState.LOADING);
			}
		});
	}

	@Subscribe
	public void onPreMapLoad(PreMapLoad event)
	{
		Scene scene = event.getScene();
		if (scene == null)
		{
			return;
		}

		recolorScene(scene);
	}

	@Subscribe
	public void onOverheadTextChanged(OverheadTextChanged event)
	{
		npcDialogueReplacer.onOverheadTextChanged(event.getActor());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(() ->
			{
				if (config.addFire())
				{
					fireSpawner.spawnFires(client);
				}
				if (config.replaceTreesBushes())
				{
					treeReplacer.replaceTrees(client);
				}
			});
		}
	}

	private void recolorScene(Scene scene)
	{
		Tile[][][] extTiles = scene.getExtendedTiles();
		Tile[][][] stdTiles = scene.getTiles();

		if (extTiles == null || stdTiles == null)
		{
			return;
		}

		int baseX = scene.getBaseX();
		int baseY = scene.getBaseY();
		int offset = computeExtendedOffset(stdTiles, extTiles);

		int recolored = 0;

		for (int z = 0; z < extTiles.length; z++)
		{
			for (int x = 0; x < extTiles[z].length; x++)
			{
				for (int y = 0; y < extTiles[z][x].length; y++)
				{
					Tile tile = extTiles[z][x][y];
					if (tile == null)
					{
						continue;
					}

					int worldX = baseX + x - offset;
					int worldY = baseY + y - offset;
					int regionId = ((worldX >> 6) << 8) | (worldY >> 6);

					if (!MisthalinRegion.isInRegion(regionId, worldX, worldY))
					{
						continue;
					}

					recolored += recolorTile(tile);
				}
			}
		}

		log.info("[LMOF] Recolored {} tile surfaces", recolored);
	}

	private int recolorTile(Tile tile)
	{
		int count = 0;

		SceneTilePaint paint = tile.getSceneTilePaint();
		if (paint != null)
		{
			if (paint.getTexture() == WATER_TEXTURE)
			{
				paint.setTexture(LAVA_TEXTURE);
				tile.setSceneTilePaint(paint);
				count++;
			}
			else if (paint.getTexture() == -1)
			{
				paint.setNwColor(fireColorMap.getFireColor(paint.getNwColor()));
				paint.setNeColor(fireColorMap.getFireColor(paint.getNeColor()));
				paint.setSwColor(fireColorMap.getFireColor(paint.getSwColor()));
				paint.setSeColor(fireColorMap.getFireColor(paint.getSeColor()));
				tile.setSceneTilePaint(paint);
				count++;
			}
		}

		SceneTileModel model = tile.getSceneTileModel();
		if (model != null)
		{
			recolorTileModel(model);
			tile.setSceneTileModel(model);
			count++;
		}

		return count;
	}

	private void recolorTileModel(SceneTileModel model)
	{
		int[] colorsA = model.getTriangleColorA();
		int[] colorsB = model.getTriangleColorB();
		int[] colorsC = model.getTriangleColorC();
		int[] textureIds = model.getTriangleTextureId();

		if (colorsA == null || colorsB == null || colorsC == null)
		{
			return;
		}

		for (int i = 0; i < colorsA.length; i++)
		{
			if (textureIds != null && i < textureIds.length)
			{
				if (textureIds[i] == WATER_TEXTURE)
				{
					textureIds[i] = LAVA_TEXTURE;
					continue;
				}
				else if (textureIds[i] != -1)
				{
					continue;
				}
			}

			colorsA[i] = fireColorMap.getFireColor(colorsA[i]);
			colorsB[i] = fireColorMap.getFireColor(colorsB[i]);
			colorsC[i] = fireColorMap.getFireColor(colorsC[i]);
		}
	}

	private static int computeExtendedOffset(Tile[][][] stdTiles, Tile[][][] extTiles)
	{
		int stdSize = stdTiles.length > 0 ? stdTiles[0].length : 0;
		int extSize = extTiles.length > 0 ? extTiles[0].length : 0;
		return (extSize - stdSize) / 2;
	}

	@Provides
	LightMisthalinOnFireConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(LightMisthalinOnFireConfig.class);
	}
}

package com.lmof;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Animation;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;

@Slf4j
public class FireSpawner
{
	private static final int FIRE_1X1_MODEL_ID = 26584;
	private static final int FIRE_1X1_ANIM_ID = 6646;
	private static final int FIRE_2X2_MODEL_ID = 26582;
	private static final int FIRE_2X2_ANIM_ID = 6645;

	private static final int REGION_SIZE = 64;
	private static final int SPACING = 8;

	private final List<RuneLiteObject> spawnedFires = new ArrayList<>();

	public void spawnFires(Client client)
	{
		clearFires();

		Model fire1x1Model = client.loadModel(FIRE_1X1_MODEL_ID);
		Model fire2x2Model = client.loadModel(FIRE_2X2_MODEL_ID);
		Animation fire1x1Anim = client.loadAnimation(FIRE_1X1_ANIM_ID);
		Animation fire2x2Anim = client.loadAnimation(FIRE_2X2_ANIM_ID);

		if (fire1x1Model == null || fire2x2Model == null)
		{
			log.warn("[LMOF] Failed to load fire models");
			return;
		}

		for (int regionId : MisthalinRegion.getRegionIds())
		{
			spawnFiresInRegion(client, regionId, fire1x1Model, fire2x2Model, fire1x1Anim, fire2x2Anim);
		}

		log.info("[LMOF] Spawned {} fires", spawnedFires.size());
	}

	private void spawnFiresInRegion(Client client, int regionId,
		Model fire1x1Model, Model fire2x2Model,
		Animation fire1x1Anim, Animation fire2x2Anim)
	{
		int regionBaseX = (regionId >> 8) << 6;
		int regionBaseY = (regionId & 0xFF) << 6;
		Random rand = new Random(regionId);

		for (int rx = 0; rx < REGION_SIZE; rx += SPACING)
		{
			for (int ry = 0; ry < REGION_SIZE; ry += SPACING)
			{
				int worldX = regionBaseX + rx + rand.nextInt(SPACING);
				int worldY = regionBaseY + ry + rand.nextInt(SPACING);
				boolean use2x2 = rand.nextBoolean();

				if (!MisthalinRegion.isInRegion(regionId, worldX, worldY))
				{
					continue;
				}

				LocalPoint lp = LocalPoint.fromWorld(client.getTopLevelWorldView(),
					new WorldPoint(worldX, worldY, 0));
				if (lp == null)
				{
					continue;
				}

				RuneLiteObject fire = client.createRuneLiteObject();
				fire.setModel(use2x2 ? fire2x2Model : fire1x1Model);
				Animation anim = use2x2 ? fire2x2Anim : fire1x1Anim;
				if (anim != null)
				{
					fire.setAnimation(anim);
					fire.setShouldLoop(true);
				}
				fire.setLocation(lp, 0);
				fire.setActive(true);
				spawnedFires.add(fire);
			}
		}
	}

	public void clearFires()
	{
		for (RuneLiteObject fire : spawnedFires)
		{
			fire.setActive(false);
		}
		spawnedFires.clear();
	}
}
